 * path a Session deletion can use.
 * @param sessionId - the Session whose live Agent is torn down.
 * @returns whether a retained handle was found and disposed.
 */
async disposeAgent(sessionId) {
    const handle = this.handles.get(sessionId);
    if (handle === undefined)
        return false;
    this.handles.delete(sessionId);
    await handle.dispose();
    return true;
}

